const { test, expect } = require("@playwright/test");
const path = require("path");

test("the health summary is the first section", async ({ page }) => {
  await page.goto("file://" + path.join(__dirname, "..", "index.html"));
  await expect(page.locator("main > section").first()).toHaveAttribute("id", "health");
  await expect(page.locator("#health p").first()).toHaveText("Status: All clear");
});

test("the health section shows what changed since the prior sprint", async ({ page }) => {
  await page.goto("file://" + path.join(__dirname, "..", "index.html"));
  const changed = page.locator("#health p", { hasText: "Changed: Cycle time improved by 2 days" });
  await expect(changed).toHaveCount(1);
  await expect(changed).toHaveText("Changed: Cycle time improved by 2 days");
});

test("the changed paragraph is ordered after status and before the current sprint section", async ({ page }) => {
  await page.goto("file://" + path.join(__dirname, "..", "index.html"));
  const healthParagraphs = page.locator("#health p");
  await expect(healthParagraphs).toHaveCount(2);
  await expect(healthParagraphs.nth(0)).toHaveText("Status: All clear");
  await expect(healthParagraphs.nth(1)).toHaveText("Changed: Cycle time improved by 2 days");
  const sections = page.locator("main > section");
  await expect(sections.nth(0)).toHaveAttribute("id", "health");
  await expect(sections.nth(1)).toHaveAttribute("id", "current");
});
